# -*- coding: utf-8 -*-
import json, os, re
from pathlib import Path

ROOT = Path("D:/repository")
SKIP = {"skills", "OpenViking", "all", "node_modules", "dist", ".git", "build", "coverage", ".nuxt", "unpackage"}
EXTS = {".vue", ".js", ".ts", ".jsx", ".tsx", ".py", ".json", ".scss", ".css"}

# build basename index
idx = {}
count = 0
for proj in ROOT.iterdir():
    if not proj.is_dir() or proj.name in SKIP:
        continue
    for dirpath, dirnames, filenames in os.walk(proj):
        dirnames[:] = [d for d in dirnames if d not in SKIP]
        for fn in filenames:
            p = Path(fn)
            if p.suffix.lower() in EXTS:
                idx.setdefault(fn, []).append(os.path.join(dirpath, fn).replace("\\", "/"))
                count += 1
print("INDEX files:", count, "unique basenames:", len(idx))

data = json.load(open("C:/Users/Administrator/.dsh/cache/memory-audit/select.json", encoding="utf-8"))
out = []
for i, c in enumerate(data["candidates"]):
    content = c["content"]
    # candidate filenames (with extension)
    files = set(re.findall(r"[A-Za-z0-9_\-\.]+\.(?:vue|js|ts|jsx|tsx|py|scss|css)", content))
    hits = {}
    for f in files:
        base = f.split("/")[-1]
        if base in idx:
            hits[base] = idx[base][:4]
    out.append({"n": i+1, "uri": c["uri"].split("/")[-1],
                "files": sorted(files), "hits": hits})

with open("C:/Users/Administrator/.dsh/cache/memory-audit/check_out.json", "w", encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print("WROTE check_out.json", len(out))

# -*- coding: utf-8 -*-
import json, os, re
from pathlib import Path
from collections import defaultdict

ROOT = Path("D:/repository")
SKIP = {"skills","OpenViking","all","node_modules","dist",".git","build","coverage",".nuxt","unpackage",".cache","temp"}
EXTS = {".vue",".js",".ts",".jsx",".tsx",".py"}
COMMON = {"index","detail.vue","index.vue","methods","computed","window","getElementById",
          "scrollTop","showSummary","formMode","bizState","base64","request","project",
          "const","return","function","include","extracted","source","cursor","project2.0"}

data = json.load(open("C:/Users/Administrator/.dsh/cache/memory-audit/select.json", encoding="utf-8"))
# token -> set(memory numbers)
tok2mem = defaultdict(set)
mem2tok = defaultdict(set)
for i, c in enumerate(data["candidates"]):
    content = c["content"]
    toks = set()
    # backtick content
    for m in re.findall(r"`([^`\n]{4,80})`", content):
        toks.add(m)
    # camelCase identifiers with uppercase, len>=7
    for m in re.findall(r"\b[a-zA-Z][a-zA-Z0-9_]{6,}\b", content):
        if re.search(r"[A-Z]", m):
            toks.add(m)
    # snake lowercase >=9
    for m in re.findall(r"\b[a-z][a-z0-9_]{8,}\b", content):
        toks.add(m)
    # api paths
    for m in re.findall(r"/[a-zA-Z][\w/.\-]{7,}", content):
        toks.add(m)
    clean = set()
    for t in toks:
        t = t.strip().strip('/')
        if len(t) < 6 or t.lower() in COMMON or ' ' in t:
            continue
        if t.count('/')==0 and not re.search(r"[A-Z_]", t):
            continue
        clean.add(t)
    for t in clean:
        tok2mem[t].add(i+1); mem2tok[i+1].add(t)

# scan files with one big alternation regex per all tokens, but map by token groups to limit size
all_tokens = sorted(tok2mem.keys(), key=len, reverse=True)
# build pattern: longest first to prefer specific
pattern = re.compile("|".join(re.escape(t) for t in all_tokens))
# token -> list of (project, relpath)
tok_hits = defaultdict(list)
scanned = 0
for proj in ROOT.iterdir():
    if not proj.is_dir() or proj.name in SKIP:
        continue
    for dirpath, dirnames, filenames in os.walk(proj):
        dirnames[:] = [d for d in dirnames if d not in SKIP]
        for fn in filenames:
            p = Path(fn)
            if p.suffix.lower() not in EXTS:
                continue
            fp = os.path.join(dirpath, fn)
            try:
                if os.path.getsize(fp) > 900*1024: continue
                text = open(fp, encoding="utf-8", errors="ignore").read()
            except Exception:
                continue
            scanned += 1
            found = set(pattern.findall(text))
            for t in found:
                if len(tok_hits[t]) < 6:
                    rel = os.path.relpath(fp, ROOT).replace("\\","/")
                    tok_hits[t].append(rel)
print("scanned", scanned, "files, tokens", len(all_tokens))

# per memory evidence: tokens that actually hit
out = {}
for n in sorted(mem2tok):
    ev = []
    for t in sorted(mem2tok[n], key=lambda x:-len(x)):
        if tok_hits.get(t):
            proj = tok_hits[t][0].split('/')[0]
            ev.append({"tok":t, "n":len(tok_hits[t]), "proj":proj, "where":tok_hits[t][0]})
    out[n] = ev
with open("C:/Users/Administrator/.dsh/cache/memory-audit/sym_out.json","w",encoding="utf-8") as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
# compact print: n -> count + top tokens
for n in sorted(out):
    ev = out[n]
    top = "; ".join("%s@%s"%(e["tok"],e["proj"]) for e in ev[:6])
    print("[%02d] ev=%d | %s"%(n, len(ev), top))

